const tagsEl = $("tags"), sug = $("suggest");
let sugActive = -1, sugItems = [];
tagsEl.addEventListener("input", updateSuggest);
tagsEl.addEventListener("focus", updateSuggest);
tagsEl.addEventListener("blur", () => setTimeout(hideSuggest, 150));
tagsEl.addEventListener("keydown", e => {
  if (!sug.classList.contains("show")) return;
  if (e.key === "ArrowDown"){ e.preventDefault(); sugActive=Math.min(sugActive+1,sugItems.length-1); paintActive(); }
  else if (e.key === "ArrowUp"){ e.preventDefault(); sugActive=Math.max(sugActive-1,0); paintActive(); }
  else if (e.key === "Enter" && sugActive>=0){ e.preventDefault(); pickTag(sugItems[sugActive]); }
  else if (e.key === "Escape"){ hideSuggest(); }
});
function curToken(){ const v = tagsEl.value; const parts = v.split(","); return { token: parts[parts.length-1].trim(), parts }; }
function updateSuggest(){
  const { token } = curToken();
  const chosen = new Set(tagsEl.value.split(",").map(t=>t.trim().toLowerCase()).filter(Boolean));
  const pool = allTags().filter(t => !chosen.has(t.toLowerCase()));
  sugItems = token ? pool.filter(t => t.toLowerCase().includes(token.toLowerCase())) : pool;
  if (!sugItems.length) { hideSuggest(); return; }
  sugActive = 0;
  sug.innerHTML = '<div class="s-head">Existing tags — click to reuse</div>' +
    sugItems.map((t,i)=>`<button type="button" class="s-item${i===0?' active':''}" data-i="${i}">#${t}</button>`).join("");
  sug.querySelectorAll(".s-item").forEach(btn => btn.addEventListener("mousedown", e => { e.preventDefault(); pickTag(sugItems[+btn.dataset.i]); }));
  sug.classList.add("show");
}
function paintActive(){ sug.querySelectorAll(".s-item").forEach((b,i)=>b.classList.toggle("active", i===sugActive)); }
function pickTag(tag){
  const parts = tagsEl.value.split(","); parts[parts.length-1] = " " + tag;
  tagsEl.value = parts.join(",").replace(/^\s+/,"") + ", ";
  hideSuggest(); tagsEl.focus();
}
function hideSuggest(){ sug.classList.remove("show"); sugActive = -1; }

// --- Search ---
const searchEl = $("search");
searchEl.addEventListener("input", () => { query = searchEl.value.trim(); $("clearSearch").style.display = query ? "" : "none"; render(); });
$("clearSearch").addEventListener("click", () => { searchEl.value=""; query=""; $("clearSearch").style.display="none"; render(); searchEl.focus(); });
function matches(b, q){
  const hay = [b.title, b.desc, b.note, b.url, b.tags.join(" ")].join(" ").toLowerCase();
  return q.toLowerCase().split(/\s+/).filter(Boolean).every(term => hay.includes(term));

