// --- Browse by tag ---
// Two interaction variants, chosen by ?browse= for side-by-side comparison:
//   panel : a "Browse by tag" bar of all tags (with counts) above the list
//   chips : click a tag chip on any bookmark card
const BROWSE = new URLSearchParams(location.search).get("browse") === "chips" ? "chips" : "panel";
let tagFilter = null;
function tagCounts(){ const c = {}; bookmarks.forEach(b => b.tags.forEach(t => c[t] = (c[t]||0)+1)); return c; }
function renderTagbar(){
  const bar = $("tagbar");
  if (BROWSE !== "panel") { bar.style.display = "none"; return; }
  const counts = tagCounts(); const tags = Object.keys(counts).sort();
  if (!tags.length) { bar.style.display = "none"; return; }
  bar.style.display = "";
  bar.innerHTML = '<span class="tagbar-label">Browse by tag:</span>' +
    tags.map(t => `<button class="tagbtn${tagFilter===t?' active':''}" data-t="${esc(t)}">#${esc(t)} <span class="c">${counts[t]}</span></button>`).join("");
  bar.querySelectorAll(".tagbtn").forEach(btn => btn.addEventListener("click", () => setTagFilter(btn.dataset.t === tagFilter ? null : btn.dataset.t)));
}
function setTagFilter(t){ tagFilter = t; render(); }

// --- Render ---
function esc(s){ return (s||"").replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }

