let query = "";

const $ = id => document.getElementById(id);
$("fetchBtn").addEventListener("click", startCapture);
$("url").addEventListener("keydown", e => { if (e.key === "Enter") startCapture(); });
$("saveBtn").addEventListener("click", commitSave);
$("cancelBtn").addEventListener("click", resetCapture);

function allTags(){ const s = new Set(); bookmarks.forEach(b => b.tags.forEach(t => s.add(t))); return [...s].sort(); }

function startCapture() {
  const url = $("url").value.trim();
  if (!url) { $("url").focus(); return; }
  const key = normUrl(url);
  const existing = bookmarks.findIndex(b => normUrl(b.url) === key);
  $("details").classList.remove("show");
  $("fetching").classList.add("show");
  $("fetchBtn").disabled = true;
  setTimeout(() => {
    if (existing >= 0) {
      openEdit(existing);
    } else {
      const meta = simulateFetch(url);
      pending = { url, meta }; editIndex = -1;
      fillForm({ url, title: meta.title, desc: meta.desc, tags: [], note: "", readLater: false, meta }, false);
    }
    $("fetching").classList.remove("show");
    $("details").classList.add("show");
    $("fetchBtn").disabled = false;
    $("title").focus();
  }, 750);
}

function openEdit(i){
  const b = bookmarks[i];
  editIndex = i; pending = { url: b.url, meta: b.meta };
  fillForm(b, true);
}

function fillForm(b, isEdit){
  $("title").value = b.title; $("desc").value = b.desc;
  $("tags").value = b.tags.join(", "); $("note").value = b.note || "";
  $("readLater").checked = !!b.readLater;
  const m = b.meta;
  const fav = $("favBox");
  fav.style.background = m.favColor; fav.textContent = m.favLetter;
  const img = new Image(); img.onload = () => { fav.innerHTML = ""; fav.appendChild(img); };
  img.src = m.favUrl;
  const pv = $("previewBox"); pv.style.background = m.previewGrad; pv.textContent = m.previewLabel;
  const note = $("autofillNote");
  if (isEdit) { note.classList.add("edit"); note.textContent = "↩ You've saved this link before — you're editing your existing bookmark, not making a duplicate"; }
  else { note.classList.remove("edit"); note.textContent = "✓ Filled in automatically from the page — adjust anything you like"; }
  hideSuggest();
}

