function setTagFilter(t){ tagFilter = t; render(); }
function setSort(m){ sortMode = m; try { localStorage.setItem("bm.sort", m); } catch(e){} render(); }
function sortBookmarks(arr){
  const a = arr.slice();
  if (sortMode === "oldest") a.sort((x,y) => x.addedAt - y.addedAt);
  else if (sortMode === "title-az") a.sort((x,y) => x.title.localeCompare(y.title));
  else if (sortMode === "title-za") a.sort((x,y) => y.title.localeCompare(x.title));
  else a.sort((x,y) => y.addedAt - x.addedAt); // newest
  return a;
}
function renderSort(){
  const el = $("sortctl");
  if (SORT_UI === "buttons") {
    el.innerHTML = '<span class="sortlabel">Sort by</span>' +
      SORT_OPTS.map(([v,l]) => `<button class="sortbtn${sortMode===v?' active':''}" data-s="${v}">${l}</button>`).join("");
    el.querySelectorAll(".sortbtn").forEach(b => b.onclick = () => setSort(b.dataset.s));
  } else {
    el.innerHTML = '<label class="sortlabel" for="sortSelect">Sort by</label><select id="sortSelect">' +
      SORT_OPTS.map(([v,l]) => `<option value="${v}"${sortMode===v?' selected':''}>${l}</option>`).join("") + "</select>";
    $("sortSelect").onchange = e => setSort(e.target.value);
  }
}

