215	<script>
216	// --- Simulated page-metadata lookup (prototype stand-in for real page reading) ---
217	const KNOWN = {
218	  "stripe.com": { title: "Stripe | Payment Processing Platform for the Internet",
219	    desc: "Stripe powers online payments for businesses of every size with a suite of developer-first APIs." },
220	  "figma.com": { title: "Figma: The Collaborative Interface Design Tool",
221	    desc: "Design, prototype, and gather feedback all in one place with Figma." },
222	  "nytimes.com": { title: "Breaking News, World News & Multimedia — The New York Times",
223	    desc: "Live news, investigations, opinion, photos and video from the reporters of The New York Times." },
224	  "css-tricks.com": { title: "A Complete Guide to Flexbox | CSS-Tricks",
225	    desc: "Our comprehensive guide to CSS flexbox layout, explaining everything about flexbox properties for parent and children." }
226	};
227	function hue(str){ let h=0; for(let i=0;i<str.length;i++) h=(h*31+str.charCodeAt(i))%360; return h; }
228	function simulateFetch(url) {
229	  let host = "", path = "";
230	  try { const u = new URL(url); host = u.hostname.replace(/^www\./,""); path = u.pathname; }
