  else if (m.failed) { note.classList.add("failed"); note.textContent = "⚠ We couldn't read this page automatically — you can still add it and fill in the details yourself."; $("title").placeholder = "Type a title for this link"; }
  else { note.textContent = "✓ Filled in automatically from the page — adjust anything you like"; }
  $("saveBtn").textContent = (mode === "edit" || mode === "dup") ? "Save changes" : "Add to collection";
  hideSuggest();
}

function commitSave() {
  const norm = normalizeInput($("editUrl").value);
  if (!norm.ok) { $("formError").textContent = "⚠ " + norm.reason; $("formError").style.display = ""; $("editUrl").focus(); return; }
  const key = normUrl(norm.url);
  const clash = bookmarks.findIndex((b, i) => i !== editIndex && normUrl(b.url) === key);
  if (clash >= 0) { $("formError").textContent = "⚠ Another bookmark already uses this address."; $("formError").style.display = ""; $("editUrl").focus(); return; }
  const tags = $("tags").value.split(",").map(t => t.trim()).filter(Boolean);
  const rec = {
    url: norm.url,
    title: $("title").value.trim() || norm.url,
    desc: $("desc").value.trim(),
    note: $("note").value.trim(),
    tags, readLater: $("readLater").checked,
    meta: pending.meta, archived: editIndex >= 0 ? bookmarks[editIndex].archived : false
  };
  if (editIndex >= 0) { rec.addedAt = bookmarks[editIndex].addedAt; bookmarks[editIndex] = rec; }
  else { rec.addedAt = Date.now(); bookmarks.unshift(rec); }
  resetCapture(); render();
}

function resetCapture() {
  pending = null; editIndex = -1;
  $("url").value = ""; $("details").classList.remove("show");
  $("fetching").classList.remove("show"); $("fetchBtn").disabled = false;
  $("formError").style.display = "none"; $("saveBtn").textContent = "Add to collection";
  hideSuggest(); $("url").focus();
}

