//   toggle : a quiet on/off control on every card
//   action : a verb button that reads "Mark as read" / "Save to read later" by context
const RL_MODE = new URLSearchParams(location.search).get("rl") === "toggle" ? "toggle" : "action"; // default: verb buttons
// Sort control appearance, chosen by ?sortui= for comparison: "dropdown" | "buttons"
const SORT_UI = new URLSearchParams(location.search).get("sortui") === "buttons" ? "buttons" : "dropdown";
const SORT_OPTS = [["newest","Newest first"],["oldest","Oldest first"],["title-az","Title A–Z"],["title-za","Title Z–A"]];
let sortMode = "newest";
try { const saved = localStorage.getItem("bm.sort"); if (saved && SORT_OPTS.some(o => o[0]===saved)) sortMode = saved; } catch(e){}
let tagFilter = null;
let view = "all"; // "all" | "unread"
function tagCounts(){ const c = {}; bookmarks.forEach(b => b.tags.forEach(t => c[t] = (c[t]||0)+1)); return c; }
function renderTagbar(){
  const bar = $("tagbar");
  if (BROWSE !== "panel" && BROWSE !== "both") { bar.style.display = "none"; return; }
  const counts = tagCounts(); const tags = Object.keys(counts).sort();
  if (!tags.length) { bar.style.display = "none"; return; }
  bar.style.display = "";
  bar.innerHTML = '<span class="tagbar-label">Browse by tag:</span>' +
    tags.map(t => `<button class="tagbtn${tagFilter===t?' active':''}" data-t="${esc(t)}">#${esc(t)} <span class="c">${counts[t]}</span></button>`).join("");
  bar.querySelectorAll(".tagbtn").forEach(btn => btn.addEventListener("click", () => setTagFilter(btn.dataset.t === tagFilter ? null : btn.dataset.t)));
}
function setTagFilter(t){ tagFilter = t; render(); }
function setSort(m){ sortMode = m; try { localStorage.setItem("bm.sort", m); } catch(e){} render(); }
function sortBookmarks(arr){
  const a = arr.slice();
  if (sortMode === "oldest") a.sort((x,y) => x.addedAt - y.addedAt);
  else if (sortMode === "title-az") a.sort((x,y) => x.title.localeCompare(y.title));
  else if (sortMode === "title-za") a.sort((x,y) => y.title.localeCompare(x.title));
  else a.sort((x,y) => y.addedAt - x.addedAt); // newest
  return a;
}
function renderSort(){
  const el = $("sortctl");
  if (SORT_UI === "buttons") {
    el.innerHTML = '<span class="sortlabel">Sort by</span>' +
      SORT_OPTS.map(([v,l]) => `<button class="sortbtn${sortMode===v?' active':''}" data-s="${v}">${l}</button>`).join("");
    el.querySelectorAll(".sortbtn").forEach(b => b.onclick = () => setSort(b.dataset.s));
  } else {
    el.innerHTML = '<label class="sortlabel" for="sortSelect">Sort by</label><select id="sortSelect">' +
      SORT_OPTS.map(([v,l]) => `<option value="${v}"${sortMode===v?' selected':''}>${l}</option>`).join("") + "</select>";

