  if (b.readLater) return `<button class="rlbtn action on" data-url="${esc(b.url)}" data-act="read">✓ Mark as read</button>`;
  return `<button class="rlbtn action" data-url="${esc(b.url)}" data-act="later">☆ Save to read later</button>`;
}
function cardActions(b){
  if (confirmDelete && normUrl(confirmDelete) === normUrl(b.url)) {
    return `<span class="confirm-msg">Delete this permanently?</span>` +
      `<button class="rlbtn danger" data-url="${esc(b.url)}" data-act="del-yes">Delete</button>` +
      `<button class="rlbtn" data-url="${esc(b.url)}" data-act="del-no">Cancel</button>`;
  }
  const rl = rlButton(b);
  const edit = `<button class="rlbtn" data-url="${esc(b.url)}" data-act="edit">✎ Edit</button>`;
  const del = `<button class="rlbtn danger" data-url="${esc(b.url)}" data-act="del-ask">🗑 Delete</button>`;
  if (ACTIONS_UI === "menu") {
    return `${rl}<span class="cardmenu"><button class="rlbtn menubtn" data-url="${esc(b.url)}" data-act="menu">⋯ More</button><span class="menu">${edit}${del}</span></span>`;
  }
  return `${rl} ${edit} ${del}`;
}
function applyCardAction(url, act){
  const key = normUrl(url); const bm = bookmarks.find(b => normUrl(b.url) === key);
  if (act === "menu") { openMenu = (openMenu === key) ? null : key; render(); return; }
  if (!bm) return;
  if (act === "toggle") bm.readLater = !bm.readLater;
  else if (act === "read") bm.readLater = false;
  else if (act === "later") bm.readLater = true;
  else if (act === "edit") { openMenu = null; openEditByUrl(bm.url); return; }
  else if (act === "del-ask") { confirmDelete = bm.url; openMenu = null; }
  else if (act === "del-no") { confirmDelete = null; }
  else if (act === "del-yes") {
    const i = bookmarks.findIndex(x => normUrl(x.url) === key);
    if (i >= 0) bookmarks.splice(i, 1);
    confirmDelete = null;
  }
  render();
}

