const cq = compileQuery(query);
if (cq.error) {
  $("count").textContent = "";
  list.innerHTML = `<div class="empty error"><div class="big">⚠ ${esc(cq.error)}</div>No results are shown until the search is fixed.</div>`;
  return;
}
const scope = view === "unread" ? bookmarks.filter(b => b.readLater) : bookmarks;
let shown = cq.empty ? scope.slice() : scope.filter(b => cq.test(b));
if (tagFilter) shown = shown.filter(b => b.tags.some(x => x.toLowerCase() === tagFilter.toLowerCase()));
shown = sortBookmarks(shown);
const filtered = !cq.empty || tagFilter;
const scopeLabel = view === "unread" ? " in read later" : "";
$("count").textContent = filtered ? `(${shown.length} of ${scope.length}${scopeLabel})` : `(${scope.length}${scopeLabel})`;
if (!shown.length) {
  if (view === "unread" && !filtered) {
    list.innerHTML = `<div class="empty"><div class="big">You're all caught up 🎉</div>Nothing is waiting in read later. Turn it on for anything you want to come back to.</div>`;
  } else {
    const what = tagFilter ? `tag #${esc(tagFilter)}${query ? " with your search" : ""}` : (query ? `“${esc(query)}”` : "this view");
    list.innerHTML = `<div class="empty"><div class="big">No bookmarks for ${what}${view==='unread'?' in read later':''}</div>Try a different tag, search, or view.</div>`;
  }
  return;
}
list.innerHTML = shown.map(b => {
  const m = b.meta;
  return `<div class="card">
    <div class="body">
      <div class="head">
        <span class="card-fav" data-fav="${esc(m.favUrl)}" style="background:${m.favColor}">${esc(m.favLetter)}</span>
        <p class="title"><a href="${esc(b.url)}" target="_blank" rel="noopener">${highlight(b.title, cq.hiText)}</a></p>
        ${b.readLater ? '<span class="rl-badge">Read later</span>' : ''}
      </div>
      <div class="url">${highlight(b.url, cq.hiText)}</div>
      ${b.desc ? `<p class="desc">${highlight(b.desc, cq.hiText)}</p>` : ""}
      ${b.note ? `<p class="note">📝 ${highlight(b.note, cq.hiText)}</p>` : ""}
      ${b.tags.length ? `<div class="tags">${b.tags.map(t => { const isTag = cq.hiTag.some(x => x.toLowerCase()===t.toLowerCase()); const clk = (BROWSE==="chips"||BROWSE==="both") ? " clickable" : ""; return `<span class="tag${clk}" data-tag="${esc(t)}">#${isTag ? "<mark>"+esc(t)+"</mark>" : highlight(t, cq.hiText)}</span>`; }).join("")}</div>` : ""}
      <div class="card-actions">${cardActions(b)}</div>
    </div>
    <div class="thumb" style="background:${m.previewGrad}">${esc(m.previewLabel)}</div>
  </div>`;
}).join("");
// upgrade favicons to real images where available
list.querySelectorAll(".card-fav").forEach(el => {
  const img = new Image(); img.onload = () => { el.textContent=""; el.appendChild(img); }; img.src = el.dataset.fav;
});
list.querySelectorAll(".tag.clickable").forEach(el => el.addEventListener("click", () => setTagFilter(el.dataset.tag)));

