let confirmDelete = null; // url pending delete confirmation
let openMenu = null;      // normUrl of card whose ⋯ menu is open
let selected = new Set(); // normUrl values selected for bulk actions
let bulkTagMode = null;   // "add" | "remove" | null
let bulkConfirmDelete = false;
let lastShown = [];       // bookmarks currently shown (for "select all matching")

input.new_string:
// --- Bulk selection ---
function selectedBookmarks(){ return bookmarks.filter(b => selected.has(normUrl(b.url))); }
function toggleSelect(url, on){ const k = normUrl(url); if (on) selected.add(k); else selected.delete(k); renderBulk(); syncCardSelClasses(); }
function syncCardSelClasses(){
  document.querySelectorAll(".card").forEach(c => c.classList.toggle("selected", selected.has(normUrl(c.dataset.open))));
}
function renderBulk(){
  const el = $("bulkbar");
  if (!selected.size) { el.style.display = "none"; el.innerHTML = ""; bulkTagMode = null; bulkConfirmDelete = false; return; }
  el.style.display = "";
  const n = selected.size;
  if (bulkConfirmDelete) {
    el.innerHTML = `<span class="bulk-count">Delete ${n} bookmark${n>1?'s':''} permanently?</span>` +
      `<button class="danger" data-bulk="delete-yes">Delete ${n}</button>` +
      `<button data-bulk="delete-no">Cancel</button>`;
  } else {
    let h = `<span class="bulk-count">${n} selected</span>`;
    if (n < lastShown.length) h += `<button data-bulk="all">Select all ${lastShown.length} matching</button>`;
    h += `<button data-bulk="clear">Clear</button><span class="bulk-sep"></span>`;
    if (view === "archived") {
      h += `<button data-bulk="restore">♻ Restore</button>`;
    } else {
      h += `<button data-bulk="read">Mark as read</button><button data-bulk="unread">Mark unread</button>`;
      h += `<button data-bulk="addtags">Add tags…</button><button data-bulk="removetags">Remove tags…</button>`;
      h += `<button data-bulk="archive">🗄 Archive</button>`;
    }
    h += `<button class="danger" data-bulk="delete">🗑 Delete…</button>`;
    if (bulkTagMode) {
      h += `<span class="bulk-taginput"><input id="bulkTags" placeholder="tags, comma separated" autocomplete="off"><button data-bulk="applytags">${bulkTagMode === 'add' ? 'Add to' : 'Remove from'} ${n}</button></span>`;
    }
    el.innerHTML = h;
  }
  el.querySelectorAll("button").forEach(btn => btn.onclick = () => applyBulk(btn.dataset.bulk));
  const ti = $("bulkTags"); if (ti) { ti.focus(); ti.onkeydown = e => { if (e.key === "Enter") applyBulk("applytags"); }; }
}
function applyBulk(action){
  const targets = selectedBookmarks();
  if (action === "all") { lastShown.forEach(b => selected.add(normUrl(b.url))); render(); return; }
  if (action === "clear") { selected.clear(); bulkTagMode = null; render(); return; }
  if (action === "addtags" || action === "removetags") { bulkTagMode = action === "addtags" ? "add" : "remove"; renderBulk(); return; }
  if (action === "applytags") {
    const raw = ($("bulkTags") ? $("bulkTags").value : "");
    const tags = raw.split(",").map(t => t.trim()).filter(Boolean);
    if (tags.length) targets.forEach(b => {
      if (bulkTagMode === "add") { const set = new Set(b.tags.map(x=>x.toLowerCase())); tags.forEach(t => { if (!set.has(t.toLowerCase())) b.tags.push(t); }); }
      else { const rm = new Set(tags.map(x=>x.toLowerCase())); b.tags = b.tags.filter(t => !rm.has(t.toLowerCase())); }
    });
    bulkTagMode = null; selected.clear(); render(); return;
  }
  if (action === "read")    { targets.forEach(b => b.readLater = false); selected.clear(); render(); return; }
  if (action === "unread")  { targets.forEach(b => b.readLater = true);  selected.clear(); render(); return; }
  if (action === "archive") { targets.forEach(b => b.archived = true);   selected.clear(); render(); return; }
  if (action === "restore") { targets.forEach(b => b.archived = false);  selected.clear(); render(); return; }
  if (action === "delete")     { bulkConfirmDelete = true; renderBulk(); return; }
  if (action === "delete-no")  { bulkConfirmDelete = false; renderBulk(); return; }
  if (action === "delete-yes") {
    const keys = new Set([...selected]);
    bookmarks = bookmarks.filter(b => !keys.has(normUrl(b.url)));
    selected.clear(); bulkConfirmDelete = false; render(); return;
  }
}

// --- Render ---
function esc(s){ return (s||"").replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }

