  document.querySelectorAll(".card").forEach(c => c.classList.toggle("selected", selected.has(normUrl(c.dataset.open))));
}
function renderBulk(){
  const el = $("bulkbar");
  if (!selected.size) { el.style.display = "none"; el.innerHTML = ""; bulkTagMode = null; bulkConfirmDelete = false; return; }
