// --- Preservation (simulated in this prototype) ---
function isPdf(url){ return /\.pdf($|[?#])/i.test(url); }
function fmtDate(t){ return new Date(t).toLocaleDateString(undefined, { year:"numeric", month:"short", day:"numeric" }); }
function preservedLink(b){
  const p = b.preserved;
  const href = "preserved-copy.html?title=" + encodeURIComponent(b.title) + "&url=" + encodeURIComponent(b.url) + "&kind=" + p.kind + "&at=" + p.at;
  const label = p.kind === "pdf" ? "Preserved PDF" : "Preserved copy";
  return `<a class="pres done" href="${esc(href)}" target="_blank" rel="noopener">🛡 ${label} · ${fmtDate(p.at)} · View</a>`;
}
function preservationRow(b){
  const parts = [];
  if (b._preserving) parts.push(`<span class="pres pending">🛡 Preserving a copy…</span>`);
