// --- Import / Export (standard Netscape bookmark HTML) ---
function exportBookmarks(){
  const lines = ['<!DOCTYPE NETSCAPE-Bookmark-file-1>',
    '<META HTTP-EQUIV="Content-Type" CONTENT="text/html; charset=UTF-8">',
    '<TITLE>Bookmarks</TITLE>', '<H1>Bookmarks</H1>', '<DL><p>'];
  bookmarks.forEach(b => {
    const add = Math.floor((b.addedAt || Date.now()) / 1000);
    let a = `    <DT><A HREF="${esc(b.url)}" ADD_DATE="${add}"`;
    if (b.tags.length) a += ` TAGS="${esc(b.tags.join(","))}"`;
    a += `>${esc(b.title)}</A>`;
    lines.push(a);
    if (b.desc) lines.push(`    <DD>${esc(b.desc)}`);
  });
  lines.push('</DL><p>');
  const blob = new Blob([lines.join("\n")], { type: "text/html" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a"); a.href = url; a.download = "bookmarks.html"; a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  showIoMsg(`Exported ${bookmarks.length} bookmark${bookmarks.length===1?"":"s"}`);
}
function importBookmarksFromText(text){
  const doc = new DOMParser().parseFromString(text, "text/html");
  const anchors = [...doc.querySelectorAll("a[href]")];
  const existing = new Set(bookmarks.map(b => normUrl(b.url)));
  let added = 0, dup = 0, skipped = 0;
  anchors.forEach(a => {
    const url = a.getAttribute("href") || "";
    if (!/^https?:/i.test(url)) { skipped++; return; }
    const key = normUrl(url);
    if (existing.has(key)) { dup++; return; }
    const title = (a.textContent || "").trim() || url;
    const tagsAttr = a.getAttribute("tags") || "";
    const tags = tagsAttr.split(",").map(t => t.trim()).filter(Boolean);
    const add = a.getAttribute("add_date");
    const addedAt = add && /^\d+$/.test(add) ? Number(add) * 1000 : Date.now();
    let desc = "";
    const dt = a.closest("dt");
    if (dt && dt.nextElementSibling && dt.nextElementSibling.tagName === "DD") desc = dt.nextElementSibling.textContent.trim();
    bookmarks.push({ url, title, desc, note: "", tags, readLater: false, archived: false, addedAt, meta: simulateFetch(url) });
    existing.add(key); added++;
  });
  render();
  return { added, dup, skipped, total: anchors.length };
}
