.settings-panel { background: #fff; border-radius: 14px; width: 100%; max-width: 520px; box-shadow: 0 12px 40px rgba(16,24,40,.28); overflow: hidden; }
.settings-head { display: flex; align-items: center; justify-content: space-between; padding: 16px 20px; border-bottom: 1px solid var(--line); }
.settings-head h2 { font-size: 17px; margin: 0; }
.settings-head button { background: #eef1f5; border: none; border-radius: 8px; width: 30px; height: 30px; font-size: 14px; cursor: pointer; }
.settings-sec { padding: 16px 20px; border-bottom: 1px solid var(--line); }
.settings-sec:last-child { border-bottom: none; }
.settings-sec h3 { font-size: 12px; text-transform: uppercase; letter-spacing: .4px; color: var(--muted); margin: 0 0 12px; }
.set-row { display: flex; align-items: center; gap: 12px; margin-bottom: 12px; }
