.loadmore .lm-count { color:var(--muted); font-weight:500; }

.settings-overlay { position:fixed; inset:0; background:rgba(16,24,40,.42); display:flex; align-items:flex-start; justify-content:center; z-index:50; padding:40px 16px; }
.settings-panel { background:#fff; border-radius:14px; width:100%; max-width:520px; box-shadow:0 12px 40px rgba(16,24,40,.28); overflow:hidden; }
.settings-head { display:flex; align-items:center; justify-content:space-between; padding:16px 20px; border-bottom:1px solid var(--line); }
.settings-head h2 { font-size:17px; margin:0; text-transform:none; letter-spacing:0; color:var(--ink); }
.settings-head button { background:#eef1f5; color:var(--ink); border-radius:8px; width:30px; height:30px; padding:0; }
.settings-sec { padding:16px 20px; border-bottom:1px solid var(--line); }
.settings-sec:last-child { border-bottom:none; }
.settings-sec h3 { font-size:12px; text-transform:uppercase; letter-spacing:.4px; color:var(--muted); margin:0 0 12px; }
.set-row { display:flex; align-items:center; gap:12px; margin-bottom:12px; }
.set-row > label { flex:0 0 120px; font-size:13.5px; font-weight:600; }
.set-row select { width:auto; flex:1 1 auto; }
.set-actions { display:flex; gap:8px; }
.set-note { font-size:12px; color:var(--muted); margin:4px 0 0; }
.segmented { display:inline-flex; background:#eef1f5; border-radius:8px; padding:3px; gap:3px; }
.segmented .seg { background:transparent; padding:6px 13px; border-radius:6px; font-size:13px; color:#47515f; }
.segmented .seg.active { background:#fff; color:var(--ink); box-shadow:var(--shadow); }
[hidden] { display:none !important; }

