.set-actions { display:flex; gap:8px; }
.set-note { font-size:12px; color:var(--muted); margin:4px 0 0; }
.segmented { display:inline-flex; background:#eef1f5; border-radius:8px; padding:3px; gap:3px; }
.segmented .seg { background:transparent; padding:6px 13px; border-radius:6px; font-size:13px; color:#47515f; }
