// ---- Boot -----------------------------------------------------------------
async function boot() {
  const res = await api("GET", "/api/state");
  if (res.ok) state = res.data;
  const p = state.prefs || {};
  if (p.sort && SORT_OPTS.some((o) => o[0] === p.sort)) sortMode = p.sort;
  if (p.pagesize && PAGE_OPTS.some((o) => o[0] === p.pagesize)) pageSize = p.pagesize;
